  about: { title: 'A propos de {{brand}}', seoDesc: 'Decouvrez {{brand}}, notre mission, nos valeurs.', whatTitle: 'Ce que nous faisons', whatBody: '{{brand}} est un convertisseur de fichiers en ligne rapide, securise et facile. Nous prenons en charge plus de 50 formats — documents, images, video, audio, archives.', whyTitle: 'Pourquoi nous l avons cree', whyBody: 'Nous etions frustres par les convertisseurs existants: lents, encombres de pubs, deroutants. Nous avons cree {{brand}} comme l outil que nous voulions — propre, rapide, respectueux de vos donnees.', diffTitle: 'Ce qui nous distingue', diff1Title: 'Confidentialite avant tout:', diff1Body: 'Vos fichiers sont automatiquement supprimes apres 24 heures. Nous ne lisons, stockons ni partageons votre contenu.', diff2Title: '50+ formats:', diff2Body: 'Documents, images, video, audio, archives et outils PDF — tout au meme endroit.', diff3Title: 'Aucune installation:', diff3Body: 'Tout fonctionne dans votre navigateur. Pas de logiciel a telecharger.', diff4Title: 'Traitement par lots:', diff4Body: 'Convertissez plusieurs fichiers a la fois. Telechargez individuellement ou en ZIP.', diff5Title: 'API developpeur:', diff5Body: 'Integrez la conversion dans vos apps avec notre API REST.', diff6Title: 'Tarification equitable:', diff6Body: 'Demarrez gratuitement, payez seulement ce que vous utilisez. Credits sans expiration.', missionTitle: 'Notre mission', missionBody: 'Rendre la conversion de fichiers simple, securisee et accessible a tous. Quelques secondes, jamais des minutes — sans compromettre votre vie privee.', valuesTitle: 'Nos valeurs', privacyTitle: 'Vie privee', privacyBody: 'Vos fichiers vous appartiennent. Nous les traitons, livrons le resultat et supprimons tout en 24 heures.', simplicityTitle: 'Simplicite', simplicityBody: 'Pas de confusion. Telechargez, choisissez un format, telechargez. C est tout.', transparencyTitle: 'Transparence', transparencyBody: 'Tarifs clairs, pas de frais caches. Vous savez toujours ce que vous payez.', qualityTitle: 'Qualite', qualityBody: 'Nous utilisons une technologie de conversion de pointe pour des resultats precis a chaque fois.' },
  faq: { title: 'Questions frequentes', subtitle: 'Reponses aux questions courantes sur {{brand}}.', seoDesc: 'Questions frequentes sur {{brand}}. Formats, tarifs, securite, limites et plus.', q1: 'Quels formats sont pris en charge?', a1: 'Nous prenons en charge plus de 50 formats incluant PDF, Word, Excel, PowerPoint, JPG, PNG, WebP, HEIC, SVG, MP4, AVI, MOV, MP3, WAV, FLAC, ZIP, RAR, 7Z et bien plus.', q2: 'Combien de temps mes fichiers sont-ils stockes?', a2: 'Tous les fichiers telecharges et convertis sont automatiquement supprimes apres 24 heures.', q3: 'Est-ce que {{brand}} est gratuit?', a3: 'Les nouveaux utilisateurs recoivent 1 credit gratuit. Vous pouvez ensuite acheter des packs a partir de €0.99.', q4: 'Comment fonctionne le systeme de credits?', a4: 'Chaque conversion utilise 1 credit. Les credits achetes sont ajoutes instantanement et n expirent jamais.', q5: 'Mes donnees sont-elles securisees?', a5: 'Oui. Tous les transferts utilisent HTTPS. Les fichiers sont supprimes apres 24 heures. Nous n accedons jamais a vos contenus.', q6: 'Quelle est la taille maximale?', a6: 'Jusqu a 200 Mo par fichier. Pour plus, contactez-nous au sujet de notre plan Business.', q7: 'A quelle vitesse les conversions se font-elles?', a7: 'La plupart en quelques secondes. Les fichiers volumineux peuvent prendre quelques minutes.', q8: 'Puis-je convertir plusieurs fichiers a la fois?', a8: 'Oui! Glissez-deposez plusieurs fichiers et telechargez-les separement ou en ZIP.', q9: 'Dois-je creer un compte?', a9: 'Oui, un compte gratuit est requis. Inscription par email ou Google en quelques secondes.', q10: 'Comment obtenir un remboursement?', a10: 'Pour tout probleme, contactez-nous dans les 14 jours pour un remboursement complet.', q11: 'Puis-je utiliser l API?', a11: 'Oui! Generez une cle API depuis votre tableau de bord et consultez la documentation.', q12: 'Que se passe-t-il en cas d echec?', a12: 'En cas d echec, votre credit n est pas debite. Reessayez ou contactez-nous.' },
